Method.Implementation:
	Set tArr = []
	set ^webService("Dashboard Start:") = $USERNAME _ ", " _  $ZDATETIME($HOROLOG,3, 1)
	set tabNms = ["270", "271", "276", "277", "835", "837P", "837I", "837D", "277CA", "999", "TA1"]
	set dtRange= [1] // ,7,30,90]

	for ind=0:1:tabNms.%Size()-1
	{
		set tbNm = tabNms.%Get(ind)
		set transaction = tbNm
		set ^webService("Dashboard TBL: "  ) = tbNm


		for dtInd=0:1:dtRange.%Size()-1
		{
			set tMin = dtRange.%Get(dtInd)

			SET dateval=$PIECE($HOROLOG,",",1)
   			SET timeval=$PIECE($HOROLOG,",",2)

   			if (tMin > 1)
   			{

				set dt = $ZDATE( ($PIECE($HOROLOG,",",1)-tMin), 3)
   			}
			else
			{
				set dt = $ZDATETime( ("" _ (dateval - tMin) _"," _ timeval), 3, 1)
			}

			set ^webService("Dashboard from") = dt
			if (tbNm = "TA1")
			{
				set whereStr = " where ProcessDtTm >= '" _ dt _ "'"
			}
			elseif (transaction [ "837")
			{

				if (transaction = "837P")
				  { 
					set whereStr = " where X12DataParentId is not null and ProcessDtTm >= '" _ dt _ "' AND VersionReleaseIndustryIdenti  = '005010X222A1'" 
				  }
				  elseif (transaction = "837I")
				  {
					  set whereStr = " where X12DataParentId is not null and ProcessDtTm >= '" _ dt _ "' AND VersionReleaseIndustryIdenti  = '005010X223A2'" 
				  }
				  else
				  {
					  set whereStr = " where X12DataParentId is not null and ProcessDtTm >= '" _ dt _ "' AND VersionReleaseIndustryIdenti  = '005010X224A2'" 
				  }
				  set tbNm = "837"
			}
			else
			{
				set whereStr = " where X12DataParentId is not null and ProcessDtTm >= '" _ dt _ "'"
			}



			if (dtInd = dtRange.%Size()-1)
			{
				set sqlStr = "Select MAX(ProcessDtTm) as lastDtTm, count(*) as rowCount from IHC_X12.Data" _ tbNm _  whereStr

			}
			else
			{
				set sqlStr = "Select count(*) as rowCount from IHC_X12.Data" _ tbNm _ whereStr

			}
			Set rs = ##class(%SQL.Statement).%ExecDirect(,sqlStr )
			set ^webService("Dashboard " _ tbNm) = sqlStr _", " _rs.%SQLCODE 
			While rs.%Next() {

			    	if ( rs.%SQLCODE = 0)
			    	{

					    set cnt =  rs.%Get("rowCount")
					    if (dtInd = dtRange.%Size()-1)
						{
					    	set lastDtTm = rs.%Get("lastDtTm")
						}

					    set fromStr = $SELECT(tMin = 1:"24 hours",1: tMin _ " days")
					    set ^webService("Dashboard " _ tbNm _ " SQL") = rs.%SQLCODE _", " _ cnt _", " _rs.%ROWCOUNT
				    	Do tArr.%Push({
								"Operation":("Dashboard"),
								"ID": (ind),
								"Transaction": (transaction),
								"Count": (cnt),
								"LastProcessed": (lastDtTm),
								"Days": ("From: " _ dt _" (" _fromStr _ ")")
								})
			    	}
			}
		}

	}
	set ^webService("Dashboard size: ") = tArr.%Size()
	Do ..%SetStatusCode(200)
	return tArr

set tableName = "IHC_X12.Data270"
set ^webService(tableName _ " Start:") = $USERNAME _ ", " _  $ZDATETIME($HOROLOG,3, 1)
return ..GetRows(tableName, searchStr)

	// All Column names
	set summary = 0

	for ind=1:1:searchArr.Count()
    {
	   set param = searchArr.GetAt(ind) 
	   if ( param [ "summary")
	   {
		   set summary = 1
		   quit
	   }
    }
    if (summary = 0)
    {

		Set prop=""
		Do propertyList.Insert("ID")
		set clsNm = $REPLACE(tableName,"_",".")
		For {
			Set prop=$$$comMemberNext(clsNm,$$$cCLASSproperty,prop) Quit:prop=""
			If (' ((prop [ "OID") || (prop [ "%") ) )
			{							
				Do propertyList.Insert(prop) 
			}
		}


    }
    else // Summary from IHC.X12.SharedData
    {
	    Set prop=""
	    Do propertyList.Insert("ID")
		For {
			Set prop=$$$comMemberNext("IHC.X12.SharedData",$$$cCLASSproperty,prop) Quit:prop=""

			If (' ((prop [ "OID") || (prop [ "x12")) )
			{
				Do propertyList.Insert(prop) 
			}
		}
		set ^webService("IHC.X12.SharedData") = "Get columns: " _ propertyList.Count()
    }

	set transType = "%" _ $REPLACE(tableName, "IHC_X12.Data", "")_ "%"	
	While rs.%Next() {

    	if ( rs.%SQLCODE = 0)
    	{

    		set ^webService(tableName _ " rs: ") = rs.%SQLCODE _ " at " _ $ZDATETIME($HOROLOG,3, 1) _ ", ID: " _ (rs.%Get("ID"))
    		set innerArr = []
    		set val = ""
    		set dataType = propertyList.Count()

    		for ind=1:1:propertyList.Count()
    		{
    		    set column = propertyList.GetAt(ind)
    		    if (rs.%ROWCOUNT = 1)
    		    {
	    		    &SQL(select Type into :dataType from IHC_ITF_ITFCOMMON_X12.TransactionFields where Key =:column and TransactionCode like :transType)

		    		set dataType(column) = 	$zconvert(dataType, "l")

    		    }

    		    set val = rs.%Get(column)

    		    if ($zconvert(dataType(column), "l") [ "date")
    		    {
	    		    set dtTm = rs.%Get(column)
	    		    if ($LENGTH(dtTm) >= 17) // Range
	    		    {

						 set val =  $E(dtTm, 1, 4) _ "-"_   $E(dtTm, 5, 6) _ "-"_  $E(dtTm, 7, 8) _ " -> "
						           _ $E(dtTm, 10, 13) _ "-"_   $E(dtTm, 14, 15) _ "-"_  $E(dtTm, 16, 17)


	    		    }
	    		    elseif ($LENGTH(dtTm) >= 10) // DtTm
	    		    {

						 set val =  $E(dtTm, 1, 2) _ "-"_  $E(dtTm, 3, 4) _ "-"_  $E(dtTm, 5, 6) _ " "_  $E(dtTm, 7, 8) _ ":"_  $E(dtTm, 9, 10)
						 if ($E(dtTm, 1, 2) < 70) // Decide 19 or 20?
						 {
						 	set val = "20" _ val
						 }
						 else
						 {
							 set val = "19" _ val
						 }

	    		    }
	    		    elseif ($LENGTH(dtTm) >= 8) //YYYYMMDD
	    		    {

						 set val =  $E(dtTm, 1, 4) _ "-"_   $E(dtTm, 5, 6) _ "-"_  $E(dtTm, 7, 8) 

	    		    }
	    		    elseif ($LENGTH(dtTm) >= 6) //YYDDMM
	    		    {

						 set val =  $E(dtTm, 1, 2) _ "-"_   $E(dtTm, 3, 4) _ "-"_  $E(dtTm, 5, 6)
						 if ($E(dtTm, 1, 2) < 70) // Decide 19 or 20?
						 {
						 	set val = "20" _ val
						 }
						 else
						 {
							 set val = "19" _ val
						 }

	    		    }
	    		    else
	    		    {
		    		    set val = dtTm
	    		    }
    		    }

    		    elseif ($zconvert(dataType(column), "l") = "currency")
    		    {
	    		     // collect 3 digits as a group
	    		     set dec = $PIECE(val, ".", 2)
	    		     set matcher=##class(%Regex.Matcher).%New("(\d)(?=(\d{3})+(?!\d))")
					 set matcher.Text=$PIECE(val, ".", 1)
					 set newStr = ""

					 while matcher.Locate() 
					 {
						 // write !,  "Found ",matcher.Group," at position ",matcher.Start, !
						 if (newStr = "")
						 {
							 set newStr = $E(matcher.Text, 1, matcher.Start)
						 }

					 	 set newStr = newStr _ "," _ $E(matcher.Text, matcher.Start+1 , matcher.Start + 3)

					 } 
					 if (newStr = "")
					 {
						 set newStr = matcher.Text
					 }

					 set val = "$" _ $SELECT((dec = ""): newStr, 1 : newStr _ "." _ dec)
    		    }


    			if (ind=1)
    			{
    				set innerArr={}.%Set(column,(val))
    			}
    			else
    			{
	    			Do innerArr.%Set(column,(val))
    			}

    		}

    		Do tArr.%Push((innerArr))
    	}


	}
	set ^webService(tableName _ " array size: ") = tArr.%Size()


