   set ^webService("GetParentX12 Start") = id _ " / " _ transType _ ": " _ $ZDATETIME($HOROLOG,3, 1)
    Set tArr = []
    #dim rs As %SQL.StatementResult
    if (transType [ "837")
    {
	    set transType = "837"
    }
    set x12Stream = "", tableName = ""

    set tableName = "IHC_X12.Data" _ transType
    /**
	     "IHC_ITF_ITFCOMMON_X12." _ $CASE(transType,"270":"EligibilityRequest","271":"EligibilityResponse",
	    "276":"ClaimStatusRequest","277":"ClaimStatusResponse",
	    "835":"ClaimPayment","277CA":"ClaimAcknowledgement",
	    "837I":"Claim","837P":"Claim","837D":"Claim",
	    "999":"ImplementationAcknowledgment","277CA":"ClaimAcknowledgement",
	    1:"Unknown")
    **/


    set sqlStr = "SELECT * FROM " _ tableName _" where ID = '" _ id _ "'" 

	Set rs = ##class(%SQL.Statement).%ExecDirect(,sqlStr)

    set ^webService("GetParentX12 rs") = sqlStr _", SQLCODE: " _ rs.%SQLCODE _ " " _ $ZDATETIME($HOROLOG,3, 1)
	While rs.%Next() {

		set x12Data = ""

				set ^webService("GetParentX12 ID: ") = (rs.%Get("ID")) _", ROWCOUNT: " _ rs.%ROWCOUNT
				set x12Str = rs.%Get("x12Data")
				try 
				{ 
				   set x12Stream = rs.%Get("x12DataStream")
				} catch (er)
				{
					set ^webService("GetParentX12 x12DataStream") = "NO"
				}
				if ( ( x12Str ="" ) &&($CLASSNAME(x12Stream) [ "GlobalCharacter"))
				{

					set x12Data = "X12 is stored as a Stream, X12 Size: " _ ##class(%Stream.Object).%Open(x12Stream).Size
				}
				else
				{
					set x12Data = x12Str
				}

		    set ^webService("GetParentX12 x12Data: ") = x12Data
			Do tArr.%Push({
				"Operation":"GetParentX12",
				"ID": (rs.%Get("ID")),

				"x12Data": (x12Data)			
			})

	}
	set ^webService("GetParentX12") = "End: " _ $ZDATETIME($HOROLOG,3, 1)
	Do ..%SetStatusCode(200)

	return tArr

Set ok = 1
