set ^webService("GetRelatedTransaction Start") = GroupControlNumber _ ", " _ transType _ ": " _ InterchangeSenderID _ ", " _ InterchangeReceiverID _ ", " _ InterchangeControlNumber _ " @ " _ $ZDATETIME($HOROLOG,3, 1) Set tArr = [] #dim rs As %SQL.StatementResult set id1=InterchangeSenderID, id2=InterchangeReceiverID set tableNm = "IHC_X12.Data" _ transType
if (transType [ "005010X222") // 837 from 999 { set id2=InterchangeSenderID, id1=InterchangeReceiverID set transType = "837" set tableNm = "IHC_X12.Data" _ transType } elseif (transType [ "005010X279") // 270 from 999 { set id2=InterchangeSenderID, id1=InterchangeReceiverID set transType = "270" set tableNm = "IHC_X12.Data" _ transType } elseif (transType [ "005010X221") // 835 from 999 { set id2=InterchangeSenderID, id1=InterchangeReceiverID set transType = "835" set tableNm = "IHC_X12.Data" _ transType }
set tStatement = ##class(%SQL.Statement).%New() SET x12query = 5 SET x12query(1) = "select distinct cl.InterchangeSenderID, cl.InterchangeReceiverID, cl.InterchangeControlNumber, ack.FileName, ack.x12Data as ST, ack2.x12Data as X999, cl.x12Data as tranX12" SET x12query(2) = " from " _ tableNm _ " cl, IHC_X12.Data999 ack, IHC_X12.Data999 ack2 " SET x12query(3) = " where ack.GroupRespControlNumber = cl.GroupControlNumber AND cl.X12DataParentId is null" SET x12query(4) = " and ack.X12DataParentId = ack2.ID and ack.GroupRespVersion = cl.VersionReleaseIndustryIdenti " SET x12query(5) = " and cl.GroupControlNumber = ? and cl.InterchangeSenderID = ? and cl.InterchangeReceiverID = ?" set ^webService("GetRelatedTransaction 999 from ") = tableNm
set tStatus = tStatement.%Prepare(.x12query) if $$$ISERR(tStatus) { Do ..%SetStatusCode(200) Do tArr.%Push({ "Operation":"GetRelatedTransaction", "Error": (tStatus)})
} else { set ^webService("GetRelatedTransaction Execute") = GroupControlNumber _ ", " _ id1 _ ", " _ id2 SET rs=tStatement.%Execute(GroupControlNumber, id1, id2 )
set ^webService(tableNm _ " - GetRelatedTransaction rs") = "rs " _rs.%SQLCODE _ ", " _ $ZDATETIME($HOROLOG,3, 1) While rs.%Next() {
set ^webService("GetRelatedTransaction While") = rs.%ROWCOUNT _ ", Next " _ $ZDATETIME($HOROLOG,3, 1) Do tArr.%Push({ "Operation":"GetRelatedTransaction", "InterchangeSenderID": (rs.%Get("InterchangeSenderID")), "InterchangeReceiverID": (rs.%Get("InterchangeReceiverID")), "FileName": (rs.%Get("FileName")), "InterchangeControlNumber": (rs.%Get("InterchangeControlNumber")), "x12Data": (rs.%Get("X999")), "StX12Data": (rs.%Get("ST")), "tranX12": (rs.%Get("tranX12")) })
}
Do ..%SetStatusCode(200) } set ^webService("GetRelatedTransaction") = "End: " _ $ZDATETIME($HOROLOG,3, 1) return tArr

 set ^webService("GetRelatedEligBenefit Start") = transType _" = "_ TrnRefId _ "/"_ SubscriberId _ ": " _ InterchangeSenderID _ ", " _ InterchangeReceiverID _ ", " _ InterchangeControlNumber _ $ZDATETIME($HOROLOG,3, 1)
    Set tArr = []
    #dim rs As %SQL.StatementResult
    set tRN1RefId = ""
    set tStatement = ##class(%SQL.Statement).%New()
	SET x12query = 8
	SET x12query(1) = "select req.TrnRefId as ReqTrnId, res.TrnRefId as RespTrnId,"
	SET x12query(2) = "req.SubscriberId as ReqSubscriberId, res.SubscriberId as RespSubscriberId,"
	SET x12query(3) = "req.x12Data as ReqX12, res.x12Data as ResX12, req.FileName as reqFileName, res.FileName as resFileName"

	SET x12query(4) = " from IHC_X12.Data270 req, IHC_X12.Data271 res where "
	SET x12query(5) = " (req.TrnRefId = res.TrnRefId )"
	if (transType = "270")
	{
		SET x12query(6) = " and req.InterchangeControlNumber = ? and req.InterchangeSenderID = ? and req.InterchangeReceiverID = ?"
		SET x12query(7) = " and req.TrnRefId = ?"


		if ( SubscriberId '= "")
		{
			SET x12query(8) = " and req.SubscriberId = ? AND req.SubscriberId =  res.SubscriberId"
		}


	}
	else
	{
		SET x12query(6) = " and res.InterchangeControlNumber = ? and res.InterchangeSenderID = ? and res.InterchangeReceiverID = ?"
		SET x12query(7) = " and res.TrnRefId = ?"
		if ( SubscriberId '= "")
		{

			SET x12query(8) = " and res.SubscriberId = ? AND req.SubscriberId =  res.SubscriberId"
		}


	}

    set tStatus = tStatement.%Prepare(.x12query)
    if $$$ISERR(tStatus)
    {
	    Do ..%SetStatusCode(200)
	    Do tArr.%Push({
				"Operation":"GetRelatedTransaction",
				"Error": (tStatus)})

    }
    else
    {

	    set ^webService("GetRelatedEligBenefit Val") = SubscriberId _ ", " _ TrnRefId _ ", " _InterchangeControlNumber _ ", " _ InterchangeSenderID _ ", " _ InterchangeReceiverID
	  	if ( SubscriberId '= "")
		{
	    	SET rs=tStatement.%Execute(InterchangeControlNumber, InterchangeSenderID, InterchangeReceiverID, TrnRefId, SubscriberId)
		}
		else
		{
			SET rs=tStatement.%Execute(InterchangeControlNumber, InterchangeSenderID, InterchangeReceiverID, TrnRefId)
		}
	     set ^webService("GetRelatedEligBenefit Execute") = rs.%SQLCODE
		While rs.%Next() {

				set ^webService("GetRelatedEligBenefit") = rs.%Get("ReqX12") _ ", Next " _ $ZDATETIME($HOROLOG,3, 1)
				Do tArr.%Push({
					"Operation":"GetRelated27x",
					"ReqTrnId": (rs.%Get("ReqTrnId")),
					"RespTrnId": (rs.%Get("RespTrnId")),
					"ReqSubscriberId": (rs.%Get("ReqSubscriberId")),
					"RespSubscriberId": (rs.%Get("RespSubscriberId")),
					"ReqX12": (rs.%Get("ReqX12")),
					"ResX12": (rs.%Get("ResX12")),
					"ReqFileName": (rs.%Get("reqFileName")),
					"ResFileName": (rs.%Get("resFileName"))			
				})
				set ^webService("GetRelatedEligBenefit While") = "Pushed" _ ", " _ $ZDATETIME($HOROLOG,3, 1)
				QUIT

		}
		set ^webService("GetRelatedEligBenefit End") = tArr.%Size() _ " at " _ $ZDATETIME($HOROLOG,3, 1)
		Do ..%SetStatusCode(200)
    }
	return tArr

set ^webService("GetRelatedClaimStatus Start") = transType _" = "_ SubscriberId _ "/"_ BhtId _ ": " _ InterchangeSenderID _ ", " _ InterchangeReceiverID _ ", " _ InterchangeControlNumber _ " @"_ $ZDATETIME($HOROLOG,3, 1) Set tArr = [] #dim rs As %SQL.StatementResult
set tStatement = ##class(%SQL.Statement).%New() SET x12query = 8 SET x12query(1) = "select req.TrnRefId as ReqTrnRefId, res.TrnRefId as ResTrnRefId," SET x12query(2) = "req.BhtId as ReqBhtId, res.BhtId as ResBhtId," SET x12query(3) = "req.Subscriber as ReqSubscriber, res.Subscriber as ResSubscriber," SET x12query(4) = "req.x12Data as ReqX12, res.x12Data as ResX12, req.FileName as reqFileName, res.FileName as resFileName" SET x12query(5) = " from IHC_X12.Data276 req, IHC_X12.Data277 res where " SET x12query(6) = " (req.TrnRefId = res.TrnRefId) AND (req.BhtId = res.BhtId) AND (req.SubscriberId = res.SubscriberId)" if (transType = "276") {
SET x12query(7) = " and req.SubscriberId = ? AND req.BhtId = ? AND req.TrnRefId = ?" SET x12query(8) = " and req.InterchangeControlNumber = ? and req.InterchangeSenderID = ? and req.InterchangeReceiverID = ?"
} else {
SET x12query(7) = " and res.SubscriberId = ? AND res.BhtId = ? AND req.TrnRefId = ?" SET x12query(8) = " and res.InterchangeControlNumber = ? and res.InterchangeSenderID = ? and res.InterchangeReceiverID = ?"
} set ^webService("GetRelatedClaimStatus SQL") = x12query(8)
set tStatus = tStatement.%Prepare(.x12query) if $$$ISERR(tStatus) { Do ..%SetStatusCode(200) Do tArr.%Push({ "Operation":"GetRelatedTransaction", "Error": (tStatus)})
} else { SET rs=tStatement.%Execute(SubscriberId, BhtId, TrnRefId, InterchangeControlNumber, InterchangeSenderID, InterchangeReceiverID )
set ^webService("GetRelatedClaimStatus rs") = "CODE: " _rs.%SQLCODE _ ", " _ $ZDATETIME($HOROLOG,3, 1) While rs.%Next() {
set ^webService("GetRelatedClaimStatus While") = rs.%ROWCOUNT _ ", Next " _ $ZDATETIME($HOROLOG,3, 1) Do tArr.%Push({ "Operation":"GetRelatedClaimStatus", "ResTrnRefId": (rs.%Get("ResTrnRefId")), "ReqBhtId": (rs.%Get("ReqBhtId")), "ResBhtId": (rs.%Get("ResBhtId")), "ReqSubscriber": (rs.%Get("ReqSubscriber")), "ResSubscriber": (rs.%Get("ResSubscriber")), "ReqX12": (rs.%Get("ReqX12")), "ResX12": (rs.%Get("ResX12")), "ReqFileName": (rs.%Get("reqFileName")), "ResFileName": (rs.%Get("resFileName"))
}) set ^webService("GetRelatedClaimStatus While Push ") = (rs.%Get("ReqSubscriber"))
} set ^webService("GetRelatedClaimStatus") = "End: " _ tArr.%Size() _ " at " _ $ZDATETIME($HOROLOG,3, 1) Do ..%SetStatusCode(200) } return tArr

 set ^webService("GetRelatedClaimInfo Start") = transType _" = "_ ClaimSubmittersIdentifier _ "/"_ MonetaryAmount _ " @"_ $ZDATETIME($HOROLOG,3, 1)
    Set tArr = []
    #dim rs As %SQL.StatementResult
    set tRN1RefId = ""
    set tStatement = ##class(%SQL.Statement).%New()
	SET x12query = 6
	SET x12query(3) = "SELECT clm.x12Data as ClmX12, clmrem.x12Data as ClmRemX12, clm.FileName as clmFileName, clmrem.FileName as clmRemFileName"

	SET x12query(4) = " from IHC_X12.Data835 clmrem, IHC_X12.Data837 clm where "
	SET x12query(5) = " (ClaimSubmitterId  = ClaimId  and TotalClaimCharge = ClaimAmount)"
	if (transType = "835")
	{
		SET x12query(6) = " and ClaimSubmitterId = ?  and TotalClaimCharge = ?"

	}
	else
	{
		SET x12query(6) = " and ClaimId = ? and ClaimAmount = ? "

	}

    set tStatus = tStatement.%Prepare(.x12query)
    if $$$ISERR(tStatus)
    {
	    Do ..%SetStatusCode(200)
	   Do tArr.%Push({
				"Operation":"GetRelatedClaimInfo",
				"Error": (tStatus)})

    }
    else
    {
	    SET rs=tStatement.%Execute(ClaimSubmittersIdentifier, MonetaryAmount)

	    set ^webService("GetRelatedClaimInfo rs") = x12query(6) _ "- rs " _rs.%SQLCODE _ ", " _ $ZDATETIME($HOROLOG,3, 1)
		While rs.%Next() {

				set ^webService("GetRelatedClaimInfo While") = rs.%ROWCOUNT _ ", Next " _ $ZDATETIME($HOROLOG,3, 1)
				Do tArr.%Push({
					"Operation":"GetRelatedClaimInfo",				
					"ClmX12": (rs.%Get("ClmX12")),
					"ClmRemX12": (rs.%Get("ClmRemX12")),
					"ClmFileName": (rs.%Get("clmFileName")),
					"ClmRemFileName": (rs.%Get("clmRemFileName"))			

				})
				set ^webService("GetRelatedClaimInfo While Push ") = (rs.%Get("clmFileName"))

		}
		set ^webService("GetRelatedClaimInfo") = "End: " _ tArr.%Size() _ " at " _ $ZDATETIME($HOROLOG,3, 1)
		Do ..%SetStatusCode(200)
